def unmerge_cashier_from_restaurants(apps, schema_editor):
    db_alias = _db_alias(schema_editor)
    now = timezone.now()
    User = apps.get_model("accounts", "User")
    Workstation = apps.get_model("accounts", "Workstation")
    RoleCapability = apps.get_model("accounts", "RoleCapability")
    StaffProfile = apps.get_model("staff_operations", "StaffProfile")
    Department = apps.get_model("staff_operations", "Department")
    ShiftTemplate = apps.get_model("staff_operations", "ShiftTemplate")
    ShiftAssignment = apps.get_model("staff_operations", "ShiftAssignment")
    AuditLog = apps.get_model("audit", "AuditLog")

    summaries = AuditLog.objects.using(db_alias).filter(
        action=ACTION,
        object_type=CONFIG_OBJECT_TYPE,
        object_id=CONFIG_OBJECT_ID,
    ).order_by("-pk")
    for summary in summaries:
        metadata = summary.metadata or {}
        state = metadata.get("state_before", {})
        added_grants = metadata.get("new_waiter_capability_ids", [])
        if added_grants:
            RoleCapability.objects.using(db_alias).filter(
                role=WAITER_ROLE, capability_id__in=added_grants
            ).delete()

        user_ids = state.get("user_ids", [])
        if user_ids:
            User.objects.using(db_alias).filter(
                pk__in=user_ids, role=WAITER_ROLE
            ).update(role=CASHIER_ROLE, updated_at=now)

        for snapshot in state.get("staff_profiles", []):
            StaffProfile.objects.using(db_alias).filter(pk=snapshot["id"]).update(
                department=snapshot["department"],
                department_ref_id=snapshot["department_ref_id"],
                updated_at=now,
            )
        for snapshot in state.get("workstations", []):
            Workstation.objects.using(db_alias).filter(pk=snapshot["id"]).update(
                department=snapshot["department"], updated_at=now
            )
        for state_key, model in (
            ("shift_templates", ShiftTemplate),
            ("shift_assignments", ShiftAssignment),
        ):
            for snapshot in state.get(state_key, []):
                model.objects.using(db_alias).filter(pk=snapshot["id"]).update(
                    department=snapshot["department"], updated_at=now
                )
        for snapshot in state.get("departments", []):
            Department.objects.using(db_alias).filter(pk=snapshot["id"]).update(
                supported_roles=snapshot["supported_roles"],
                job_positions=snapshot["job_positions"],
                is_active=snapshot["is_active"],
                updated_at=now,
            )
